// Program : Liner Diophantine Equation(선형 디오팔투스 방정식)   
// Language : Java

import java.io.*;  
public class lde{  
public static void main(String[] ar) throws IOException{  
BufferedReader in = new BufferedReader(new InputStreamReader(System.in));  

int a, b, c, d, q, r, a1, b1, c1;  
int r1, r2, s, t, s1 = 1, s2 = 0, t1 = 0, t2 = 1, x, y, x0, y0, k = 0;  

System.out.println("Liner Diophantine Equation 'ax + by = c' ");  
System.out.print("input a = ");  
a = Integer.parseInt(in.readLine());  
System.out.print("input b = ");  
b = Integer.parseInt(in.readLine());  
System.out.print("input c = ");  
c = Integer.parseInt(in.readLine());  
System.out.println( a + "x + " + b + "y = " + c);  
System.out.println();

// EA; d=gcd(a,b)  
r1 = a; r2 = b;  
while(r2>0){  
q = r1/r2;  
r = r1 - q * r2;  
r1 = r2; r2 = r;  
}  
d = r1;  
System.out.println(d + " = gcd(" + a +","+ b + ")");  
System.out.println();

// if d|c then TRUE else FALSE and EXIT  
if(0 == d%c){  
System.out.println("d|c is TRUE ");  
}else if(0 == c%d){  
System.out.println("d|c is TRUE ");  
}else{  
System.out.println("d|c is FALSE ");  
System.exit(-1);  
}  
System.out.println();

// The particular  
a1 = a/d;  
b1 = b/d;  
c1 = c/d;  
System.out.println("'a1x + b1y = c1' is '" + a1 + "x + " + b1 + "y = " + c1 + "'");  
System.out.println("'a1s + b1t = 1' is '" + a1 + "s + " + b1 + "t = " + 1 + "'");  
System.out.println();

//// EEA  
r1 = a1; r2 = b1;  
while(r2 > 0){  
q = r1/r2;  
r = r1 - q * r2;  
r1 = r2; r2 = r;

s = s1 - q * s2;  
s1 = s2; s2 = s;

t = t1 - q * t2;  
t1 = t2; t2 = t;  
}  
x0 = (c/d) * s1;  
y0 = (c/d) * t1;  
System.out.println("The particular is x0 = "+ x0 + ", y0 = " + y0);  
System.out.println();

//General  
System.out.println("General is x = " + x0 + " + k(" + b + "/" + d + "), y = " + y0 + " + k(" + a + "/" + d + "), [k is integer]");   
while(k<10){  
x = x0 + k * (b/d);  
y = y0 - k * (a/d);  
k++;

System.out.print("(" + x + ", " + y + "), ");  
}  
System.out.println("...");  

}  
}

우연히 배정받은 사물함 안에서 자물쇠 하나를 주웠다.  
8가지 숫자중 4가지의 암호로 되어있는 이 흔한 기종은..   

8C4 = 8!/4!*4! = 70  
70가지 경우의 암호키 조합을 생성해낸다.  

놀랍지 않은가? 자물쇠가 고작 70가지 경우의 암호만 존재한다면  
핸드폰 타이핑 속도 500타를 돌파하는 이 시대에[참고: 네이버지식인]   
암호를 알아내는데 걸리는 시간은 1분도 채 걸리지 않을 것이다.  

그래서 그 암호키 조합들을 생각해 보았다.  




**1\. 소스코드  

**//::4/8자물쇠의 암호키 생성 알고리즘  

#include <stdio.h>  

void main(){  

int cnt = 0;

for(int i = 1;i<=8;i++){  
for(int j = i+1;j<=8;j++){  
for(int k = j+1;k<=8;k++){  
for(int l = k+1;l<=8;l++){  
printf("[%d,%d,%d,%d] ",i,j,k,l);  
cnt++;  
if(!(cnt%5)) printf("\n");  
}   
}   
}  
}  
printf("\n%d\n",cnt);  
}  

