} NODE;

NODE* insertNode(NODE*,int);  
void preorder(NODE*);  
void inorder(NODE*);  
void postorder(NODE*);

void main(){

int num, i, input;  
NODE *tree = NULL;  

printf("입력받을 노드의 수 갯수:");  
scanf("%d",&num);  
printf("%d개의 노드의 수 입력 \n", num);  
