void bubbleSort(int* dataAry, int siz){ // bubble sort

int i,j,temp;  
for(i=siz-1;i>=0;i--){  
for(j=0;j<i;j++){  
if(dataAry[j]>dataAry[j+1]){ //뒤에 값과 비교하여 크면  
temp = dataAry[j+1]; //값을 교환한다.  
dataAry[j+1] = dataAry[j];  
dataAry[j] = temp;  
}  
}  
prntData(dataAry,siz); // 배열의 내용 출력  
printf("\n");  
}

}


